def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(length, separators):
        cuts = [-1] + separators + [length]
        return [(cuts[i] + 1, cuts[i + 1])
                for i in range(len(cuts) - 1)
                if cuts[i] + 1 < cuts[i + 1]]

    row_segments = segments(h, sep_rows)
    col_segments = segments(w, sep_cols)

    # The ordinary tile color is the most common non-marker color.
    counts = {}
    for r0, r1 in row_segments:
        for c0, c1 in col_segments:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    if value != 8:
                        counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    result = []
    for r0, r1 in row_segments:
        row = []
        for c0, c1 in col_segments:
            markers = sum(grid[r][c] == 8
                          for r in range(r0, r1)
                          for c in range(c0, c1))
            row.append(1 if markers > 1 else background)
        result.append(row)
    return result
